mapper.select:
SELECT 
FROM saved_categories c
WHERE c.id = #{id}

SELECT , COALESCE(stats.item_count, 0) AS item_count, stats.last_saved_at, photo.photo_url AS latest_photo_url
WHERE c.user_id = #{userId}
AND c.visibility = 'PUBLIC'
ORDER BY COALESCE(stats.last_saved_at, c.updated_at) DESC, c.id DESC LIMIT #{limit}

mapper.update:
UPDATE saved_categories
SET name = #{name},
    cover_url = #{coverUrl},
    visibility = #{visibility},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM saved_categories
WHERE id = #{id}
  AND user_id = #{userId}
